import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import api from '../../utils/api';
import LoadingSpinner from '../../components/LoadingSpinner';
import './AllPets.css';

const AllPets = () => {
  const [pets, setPets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [species, setSpecies] = useState('All');
  const [sort, setSort] = useState('newest');
  
  // Debounced search value
  const [debouncedSearch, setDebouncedSearch] = useState('');

  // Debounce logic - waits for user to stop typing
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search);
    }, 500); // Wait 500ms after user stops typing

    return () => clearTimeout(timer);
  }, [search]);

  // Fetch pets when debouncedSearch, species, or sort changes
  useEffect(() => {
    fetchPets();
  }, [debouncedSearch, species, sort]);

  const fetchPets = async () => {
    setLoading(true);
    try {
      const res = await api.get('/pets', {
        params: { 
          search: debouncedSearch, 
          species, 
          sort 
        }
      });
      setPets(res.data);
    } catch (error) {
      console.error('Error fetching pets:', error);
    } finally {
      setLoading(false);
    }
  };

  // Handle search input change without losing focus
  const handleSearchChange = (e) => {
    setSearch(e.target.value);
  };

  // Handle species change
  const handleSpeciesChange = (e) => {
    setSpecies(e.target.value);
  };

  // Handle sort change
  const handleSortChange = (e) => {
    setSort(e.target.value);
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className="container">
      <div className="all-pets-header">
        <h1>Find Your Perfect Companion</h1>
        <p>Browse our available pets waiting for a loving home</p>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <input
            type="text"
            placeholder="Search by name..."
            value={search}
            onChange={handleSearchChange}
            autoComplete="off"
          />
        </div>
        
        <div className="filter-group">
          <select value={species} onChange={handleSpeciesChange}>
            <option value="All">All Species</option>
            <option value="Dog">Dogs</option>
            <option value="Cat">Cats</option>
            <option value="Bird">Birds</option>
            <option value="Rabbit">Rabbits</option>
            <option value="Other">Other</option>
          </select>
          
          <select value={sort} onChange={handleSortChange}>
            <option value="newest">Newest First</option>
            <option value="oldest">Oldest First</option>
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
          </select>
        </div>
      </div>

      {pets.length === 0 ? (
        <div className="no-pets">
          <p>No pets found matching your criteria.</p>
          <button 
            onClick={() => {
              setSearch('');
              setDebouncedSearch('');
              setSpecies('All');
              setSort('newest');
            }} 
            className="clear-filters-btn"
          >
            Clear Filters
          </button>
        </div>
      ) : (
        <>
          <div className="results-count">
            Found {pets.length} pet{pets.length !== 1 ? 's' : ''}
          </div>
          <div className="pets-grid">
            {pets.map((pet) => (
              <div key={pet._id} className="pet-card">
                <img src={pet.imageUrl} alt={pet.name} className="pet-card-image" />
                <div className="pet-card-content">
                  <h3>{pet.name}</h3>
                  <p>{pet.breed} • {pet.age} years • {pet.gender}</p>
                  <p className="pet-price">${pet.adoptionFee}</p>
                  <Link to={`/pets/${pet._id}`} className="details-btn">
                    View Details
                  </Link>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default AllPets;
